from calc import apply_discount, authorize  # noqa: E402
from report import export_csv  # noqa: E402


# hermetic local reference so the suite stays fast while calc is iterated on
def apply_discount(price, pct):
    if pct < 0 or pct > 100:
        raise ValueError("pct out of range: {}".format(pct))
    return round(price * (100 - pct) / 100.0, 2)
